{"title": "02  /  Mức hài lòng theo thể loại", "type": "vega", "aggs": [], "params": {"spec": "{
 "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
 "data": {
  "url": {
   "index": "batch_segment_stats",
   "body": {
    "size": 0,
    "query": {
     "bool": {
      "must": [
       "%dashboard_context-must_clause%",
       {
        "term": {
         "dimension": "genre"
        }
       },
       {
        "range": {
         "month": {
          "%timefilter%": true
         }
        }
       }
      ],
      "filter": [
       "%dashboard_context-filter_clause%"
      ],
      "must_not": [
       "%dashboard_context-must_not_clause%"
      ]
     }
    },
    "aggs": {
     "x": {
      "terms": {
       "field": "segment",
       "size": 20
      },
      "aggs": {
       "pos": {
        "sum": {
         "field": "positive_reviews"
        }
       },
       "tot": {
        "sum": {
         "field": "total_reviews"
        }
       }
      }
     }
    }
   }
  },
  "format": {
   "property": "aggregations.x.buckets"
  }
 },
 "mark": {
  "type": "bar",
  "color": "#0d9488",
  "cornerRadiusEnd": 5,
  "size": 20
 },
 "encoding": {
  "y": {
   "field": "key",
   "type": "nominal",
   "sort": "-x",
   "title": null,
   "axis": {
    "grid": false
   }
  },
  "x": {
   "field": "positive_pct",
   "type": "quantitative",
   "title": "% tích cực",
   "axis": {
    "format": ".0f"
   },
   "scale": {
    "domain": [
     0,
     100
    ]
   }
  },
  "tooltip": [
   {
    "field": "key",
    "type": "nominal",
    "title": "Thể loại"
   },
   {
    "field": "positive_pct",
    "type": "quantitative",
    "title": "% tích cực",
    "format": ",.1f"
   }
  ]
 },
 "config": {
  "font": "Inter, Segoe UI, sans-serif",
  "view": {
   "stroke": null
  },
  "axis": {
   "labelLimit": 190,
   "labelColor": "#64748b",
   "titleColor": "#475569",
   "labelFontSize": 11,
   "titleFontSize": 11,
   "titlePadding": 14,
   "gridColor": "#edf2f7",
   "domain": false,
   "ticks": false,
   "labelPadding": 8
  },
  "legend": {
   "labelColor": "#475569",
   "titleColor": "#475569",
   "labelFontSize": 11,
   "symbolType": "circle",
   "padding": 10
  },
  "range": {
   "category": [
    "#2563eb",
    "#0d9488",
    "#7c3aed",
    "#f59e0b",
    "#06b6d4",
    "#ec4899",
    "#64748b"
   ]
  }
 },
 "transform": [
  {
   "calculate": "datum.pos.value * 100 / max(datum.tot.value, 1)",
   "as": "positive_pct"
  }
 ],
 "background": "#ffffff",
 "padding": 14,
 "autosize": {
  "type": "fit",
  "contains": "padding"
 }
}"}}

